exercise.solution:
def validate_request(data):
    if not isinstance(data,dict) or set(data)-{"text","max_words"}:
        raise ValueError("Invalid fields")
    text, limit = data.get("text"), data.get("max_words",50)
    if not isinstance(text,str) or not text.strip() or type(limit) is not int or not 1 <= limit <= 200:
        raise ValueError("Invalid request")
    return {"text":text.strip(),"max_words":limit}

