def error_response(kind):
    known = {"validation":(400,False),"rate_limit":(429,True),"timeout":(504,True)}
    status,retryable = known.get(kind,(500,False))
    return {"status":status,"retryable":retryable,"code":kind if kind in known else "internal"}

