exercise.solution:
def handle_request(data):
    if not isinstance(data,dict) or set(data)-{"text","max_words"}:
        return {"error":"invalid_request"}
    text, limit = data.get("text"), data.get("max_words",50)
    if not isinstance(text,str) or not text.strip() or type(limit) is not int or not 1 <= limit <= 200:
        return {"error":"invalid_request"}
    words = text.split()[:limit]
    return {"mode":"simulated","output":" ".join(words),"word_count":len(words)}

def allow_request(timestamps, now, window, limit):
    if window <= 0 or limit <= 0:
        raise ValueError("positive window and limit required")
    return sum(now-window < t <= now for t in timestamps) < limit

def cache_key(tenant, model, payload):
    import hashlib, json
    encoded = json.dumps([tenant, model, payload], sort_keys=True, separators=(",", ":")).encode()
    return hashlib.sha256(encoded).hexdigest()

