def category_accuracy(cases):
    counts = {}
    for case in cases:
        correct, total = counts.get(case["category"], (0, 0))
        counts[case["category"]] = (correct + (case["expected"] == case["actual"]), total + 1)
    return {key: correct / total for key, (correct, total) in counts.items()}

