def handle_request(payload, model):
    text = payload.get("text")
    if not isinstance(text, str) or not text.strip(): return {"status":400,"error":"invalid_text"}
    try:
        value = model(text.strip())
    except Exception:
        return {"status":502,"error":"model_unavailable"}
    return {"status":200,"result":value}

def process_batch(payloads, model):
    responses = []
    for payload in payloads:
        text = payload.get("text")
        if not isinstance(text, str) or not text.strip():
            response = {"status":400,"error":"invalid_text"}
        else:
            try: response = {"status":200,"result":model(text.strip())}
            except Exception: response = {"status":502,"error":"model_unavailable"}
        responses.append(response)
    successes = sum(r["status"] == 200 for r in responses)
    return {"responses":responses,"successes":successes,"failures":len(responses)-successes}

tests.code:
r=process_batch([{"text":" hi "},{}],str.upper)
assert r["successes"] == 1 and r["failures"] == 1
assert r["responses"][0] == {"status":200,"result":"HI"}

def sometimes(text):
    if text == "bad": raise RuntimeError("secret")
    return text
r=process_batch([{"text":"bad"},{"text":"good"}],sometimes)
assert r["responses"][0] == {"status":502,"error":"model_unavailable"}
assert r["responses"][1] == {"status":200,"result":"good"}
assert r["successes"] == 1 and r["failures"] == 1
